//! Regression: back faces are drawn as Blender draws them. Solid (Workbench) and the viewport data
//! passes draw a single-sided plane from behind unless the scene's `show_backface_culling` is on.
//! Realtime Beauty (EEVEE) culls single-sided material faces seen from behind. A single plane is
//! seen from both sides in each case, so the back face is the bottom view. The oracle is Blender
//! 5.2.2's renders of the same plane, generated by the committed script
//! `fixtures/native_oracle/backface_coverage.py`.

#[path = "common/blender_checked.rs"]
mod blender_checked;
#[path = "common/native_oracle.rs"]
#[expect(
    dead_code,
    reason = "each test binary uses a subset of the shared oracle helpers"
)]
mod native_oracle;
#[path = "common/process.rs"]
mod process;

use std::{fs, io::BufReader, path::Path, process::Command};

use blender_checked::blender_executable;
use native_oracle::{
    TestResult, apply_operations, checked, loss_features, pot, pot_json, run_blender_arguments,
    write_script,
};
use serde_json::{Value, json};
use tempfile::tempdir;

/// Coverage tolerance as a fraction of the frame. Both renders cover 58 x 58 of 64 x 64 pixels
/// with no antialiasing, so an empty back face (0) or a dropped triangle is far outside it.
const COVERAGE_TOLERANCE: f64 = 0.01;

/// Blender 5.2.2 oracle: Workbench and EEVEE coverage of a plane from above and below, with each
/// culling setting (see `backface_coverage.py`).
const BACKFACE_SCRIPT: &str = include_str!("fixtures/native_oracle/backface_coverage.py");

/// Fraction of pixels in the 8-bit PNG at `path` that differ from its top-left corner.
fn lit_fraction(path: &Path) -> TestResult<f64> {
    let mut reader = png::Decoder::new(BufReader::new(fs::File::open(path)?)).read_info()?;
    let mut pixels = vec![
        0;
        reader
            .output_buffer_size()
            .ok_or("PNG output buffer size is unknown")?
    ];
    let info = reader.next_frame(&mut pixels)?;
    let channels = info.color_type.samples();
    let background = &pixels[..3];
    let lit = pixels
        .chunks_exact(channels)
        .filter(|pixel| pixel[..3] != *background)
        .count();
    Ok(lit as f64 / (info.width as usize * info.height as usize) as f64)
}

/// Runs the Blender oracle under `root` and returns its coverage per case.
fn blender_coverage(blender: &Path, root: &Path) -> TestResult<Value> {
    let oracle_png = root.join("oracle");
    fs::create_dir(&oracle_png)?;
    let script = write_script(root, "backface_coverage.py", BACKFACE_SCRIPT)?;
    let expected_json = root.join("expected.json");
    run_blender_arguments(blender, &script, None, &[&expected_json, &oracle_png])?;
    Ok(serde_json::from_slice(&fs::read(&expected_json)?)?)
}

#[test]
fn solid_preview_draws_back_faces_as_workbench_does() -> TestResult {
    let Some(blender) = blender_executable() else {
        eprintln!("skipping the back-face preview oracle; no executable Blender was found");
        return Ok(());
    };
    let root = tempdir()?;
    let expected = blender_coverage(&blender, root.path())?;

    let scene = root.path().join("scene");
    pot_json(|command| {
        command.arg("init").arg(&scene);
    })?;
    // A default plane has no material, so it is single-sided in the material model. Solid still
    // draws its back face.
    let applied = apply_operations(
        &scene,
        root.path(),
        json!([{"op": "node.create", "id": "plane", "kind": "plane", "params": {"size": 2.0}}]),
    )?;
    assert_eq!(applied["ok"], json!(true), "plane apply failed: {applied}");

    let out = root.path().join("preview");
    let preview = pot_json(|command| {
        command
            .arg("preview")
            .arg(&scene)
            .args(["--views", "top,bottom", "--mode", "solid", "--size", "64"])
            .arg("--out")
            .arg(&out);
    })?;
    let previews = preview["result"]["previews"]
        .as_array()
        .ok_or("preview result has no previews")?;
    assert_eq!(previews.len(), 2, "one preview per requested view");
    for item in previews {
        let view = item["view"].as_str().ok_or("preview has no view name")?;
        let path = Path::new(item["image"].as_str().ok_or("preview has no image path")?);
        let lit = lit_fraction(path)?;
        let want = expected[view]
            .as_f64()
            .ok_or("oracle has no coverage for the view")?;
        assert!(
            (lit - want).abs() <= COVERAGE_TOLERANCE,
            "{view} solid preview covers {lit:.4} of the frame; Blender's Workbench covers {want:.4}"
        );
    }
    Ok(())
}

#[test]
fn realtime_beauty_culls_single_sided_back_faces_as_eevee_does() -> TestResult {
    let Some(blender) = blender_executable() else {
        eprintln!("skipping the back-face beauty oracle; no executable Blender was found");
        return Ok(());
    };
    let root = tempdir()?;
    let expected = blender_coverage(&blender, root.path())?;

    let scene = root.path().join("scene");
    pot_json(|command| {
        command.arg("init").arg(&scene);
    })?;
    // Diffuse white, single-sided (`double_sided` is set false explicitly below), matching EEVEE's
    // `use_backface_culling` on. Quaternions are [x,y,z,w] (spec.md), so identity is [0,0,0,1]
    // and [1,0,0,0] is a 180° turn about X. A sun above the plane (identity, shining down -Z, as
    // Blender's sun does) lights the front face; the top camera looks down at it, and the bottom
    // camera (turned about X, at z=-5) looks up at its back face.
    let applied = apply_operations(
        &scene,
        root.path(),
        json!([
            {"op": "material.create", "id": "single", "base_color": [0.8, 0.8, 0.8, 1.0],
             "double_sided": false},
            {"op": "node.create", "id": "plane", "kind": "plane", "params": {"size": 2.0},
             "material": "single"},
            {"op": "light.create", "id": "sun", "light_type": "sun", "energy": 3.0,
             "transform": {"translation": [0.0, 0.0, 5.0], "rotation": [0.0, 0.0, 0.0, 1.0]}},
            {"op": "camera.create", "id": "camera_top", "projection": "orthographic",
             "ortho_scale": 2.2, "transform": {"translation": [0.0, 0.0, 5.0],
             "rotation": [0.0, 0.0, 0.0, 1.0]}},
            {"op": "camera.create", "id": "camera_bottom", "projection": "orthographic",
             "ortho_scale": 2.2, "transform": {"translation": [0.0, 0.0, -5.0],
             "rotation": [1.0, 0.0, 0.0, 0.0]}},
            {"op": "scene.update", "target": {"id": "scene_main"}, "set": {"camera": "camera_top"}},
            {"op": "render.update", "target": {"id": "scene_main"},
             "set": {"resolution_x": 64, "resolution_y": 64, "resolution_percentage": 100}}
        ]),
    )?;
    assert_eq!(
        applied["ok"],
        json!(true),
        "beauty scene apply failed: {applied}"
    );

    let render_view = |camera: &str| -> TestResult<std::path::PathBuf> {
        let out = root.path().join(camera);
        let mut command = pot();
        command
            .arg("render")
            .arg(&scene)
            .args([
                "--camera", camera, "--engine", "realtime", "--format", "png", "--out",
            ])
            .arg(&out)
            .arg("--json");
        checked(&mut command, "realtime beauty render")?;
        Ok(out.join("frame_0001.png"))
    };
    let top = lit_fraction(&render_view("camera_top")?)?;
    let bottom = lit_fraction(&render_view("camera_bottom")?)?;
    assert!(
        top > COVERAGE_TOLERANCE,
        "the front of the plane must render; it covers {top:.4} of the frame"
    );
    let want = expected["eevee_bottom_material_culling"]
        .as_f64()
        .ok_or("oracle has no EEVEE coverage")?;
    assert!(
        (bottom - want).abs() <= COVERAGE_TOLERANCE,
        "single-sided beauty from behind covers {bottom:.4} of the frame; EEVEE covers {want:.4}"
    );
    Ok(())
}

#[test]
fn blender_scene_backface_culling_imports_as_a_reported_loss() -> TestResult {
    let Some(blender) = blender_executable() else {
        eprintln!("skipping the backface culling import; no executable Blender was found");
        return Ok(());
    };
    let root = tempdir()?;
    // The oracle's scene-culling case must hide the back face in Workbench. The import loss below
    // reports exactly this setting, so the two checks describe the same behaviour.
    let expected = blender_coverage(&blender, root.path())?;
    let culled = expected["bottom_scene_culling"]
        .as_f64()
        .ok_or("oracle has no scene-culling coverage")?;
    assert!(
        culled < COVERAGE_TOLERANCE,
        "Blender's scene culling must hide the back face; it covers {culled:.4}"
    );

    let blend = root.path().join("culling.blend");
    // Blender-side: the scene's viewport shading culls back faces, saved to a .blend.
    let expression = format!(
        "import bpy; bpy.context.scene.display.shading.show_backface_culling = True; bpy.ops.wm.save_as_mainfile(filepath={:?})",
        blend.to_string_lossy()
    );
    checked(
        Command::new(&blender)
            .args([
                "--background",
                "--factory-startup",
                "--disable-autoexec",
                "--python-exit-code",
                "1",
                "--python-expr",
            ])
            .arg(expression),
        "saving the culling scene",
    )?;

    let project = root.path().join("project");
    pot_json(|command| {
        command.arg("init").arg(&project);
    })?;
    let import = |extra: &[&str]| {
        let mut command = pot();
        command
            .arg("import")
            .arg(&project)
            .arg("--file")
            .arg(&blend)
            .args([
                "--format",
                "blend",
                "--mode",
                "replace",
                "--base-revision",
                "0",
                "--blender",
            ])
            .arg(&blender)
            .args(extra);
        command
    };
    let strict = import(&["--json"]).output()?;
    assert!(
        !strict.status.success(),
        "a scene that culls back faces must not import silently"
    );
    let report = format!(
        "{}{}",
        String::from_utf8_lossy(&strict.stdout),
        String::from_utf8_lossy(&strict.stderr)
    );
    assert!(
        report.contains("blender.scene.display_backface_culling"),
        "the strict import must name the culling loss: {report}"
    );

    let lossy = pot_json(|command| {
        *command = import(&["--allow-lossy"]);
    })?;
    assert!(
        loss_features(&lossy).contains(&"blender.scene.display_backface_culling".to_owned()),
        "the lossy import must record the culling loss"
    );
    Ok(())
}
